  1	import {createHash} from "node:crypto";
  2	
  3	import {z} from "zod";
  4	
  5	/**
  6	 * Executor of the method `plan-meeting-brief` (v5, after the fourth independent review). Assembles
  7	 * the first deliverable only from objects in a usable state, each fact bound to the fingerprint of
  8	 * the object it cites; a conditioned, partial or open object names a gap instead of filling a block.
  9	 * Points for and against the thesis come from the stance each object declared on its facts. The
 10	 * page plan honours the number of pages asked, carries the audience's discriminator, and allows
 11	 * production only once the person confirmed that exact plan. Questions the base already answers
 12	 * are refused whatever the caller says; a question that changes nothing is not asked. A previous
 13	 * version yields a change note instead of a silent rewrite. A block is filled only with facts; a
 14	 * usable object without facts names a gap. A conditioned or open object is carried as an uncovered
 15	 * term so its finding is never silently dropped. A financial figure in a fact carries its unit.
 16	 * Without audience or form the deliverable still goes out and the page plan waits. Points for and
 17	 * against the thesis come from the stance any usable object declared, never from a list of kinds.
 18	 * Only cited objects count as used. A question is asked only after a declared search of the base
 19	 * that found no answer. A fact's unit cannot contradict the fact's own words nor the unit of the
 20	 * object it quotes; every fact names the field of the object it reproduces; a fact that asserts a
 21	 * legal event (a breach) is refused, since no object asserts one. A plan that cannot hold the pages
 22	 * asked emits the question. Every gap, open questions included, is an uncovered term. This executor
 23	 * plans; the prose of the pages is a model step downstream, never produced here.
 24	 */
 25	const nonEmpty = z.string().trim().min(1);
 26	const identifier = z.string().regex(/^[a-z][a-z0-9_.-]*$/);
 27	const sha256 = z.string().regex(/^[a-f0-9]{64}$/);
 28	const anchorSchema = z.object({document: nonEmpty, page: z.number().int().positive().optional(), note: nonEmpty.optional(), clause: nonEmpty.optional()}).strict();
 29	type Anchor = z.infer<typeof anchorSchema>;
 30	const compare = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);
 31	
 32	export const objectKinds = ["debt_ledger", "maturity_wall", "covenants", "reconciliation", "interest_schedule", "scenarios", "exit_costs", "before_after", "company_view", "performance"] as const;
 33	/** States that let an object fill a block; every other state names a gap. */
 34	const USABLE_STATES = new Set(["complete", "resolved", "closes", "declared", "compared", "diagnosed"]);
 35	
 36	export const approvedObjectSchema = z.object({
 37	  id: identifier,
 38	  kind: z.enum(objectKinds),
 39	  state: z.enum(["complete", "resolved", "closes", "declared", "compared", "diagnosed", "conditioned", "incomplete", "partial", "open_divergences", "identity_failed", "blocked"]),
 40	  fingerprint: sha256,
 41	  /** The monetary unit the object's figures are stated in, when it has any; a fact quoting a figure must carry the same unit. */
 42	  unit: nonEmpty.nullable().default(null),
 43	  /** Facts the deliverable may cite; each one is bound to the object's fingerprint, names the field it reproduces and declares its stance on the thesis. */
 44	  headlines: z.array(z.object({text: nonEmpty, stance: z.enum(["for", "against", "neutral"]), objectFingerprint: sha256, /** Unit of any figure the text carries (R$ mil, x, %); required when the text carries a thousands-separated number. */ unit: nonEmpty.nullable().default(null), /** The field of the object the fact reproduces, so a fact can be audited against the object it is bound to. */ objectPath: nonEmpty}).strict()).max(12).default([]),
 45	}).strict();
 46	
 47	export const briefRequestSchema = z.object({
 48	  turn: z.number().int().positive(),
 49	  /** The person the material is for first; the others do not change the discriminator. */
 50	  /** Null when the person has not said who the material is for; the deliverable goes out and the plan waits. */
 51	  audience: z.object({primary: nonEmpty, others: z.array(nonEmpty).default([])}).strict().nullable(),
 52	  form: z.enum(["first_deliverable", "internal_briefing", "pitch_pages", "analysis_with_scenarios", "board_deck"]).nullable(),
 53	  pages: z.number().int().positive().nullable().default(null),
 54	  /** What the sponsor said, kept verbatim. */
 55	  sponsorInstruction: z.string().nullable().default(null),
 56	  /** What the instruction left undefined, declared by the caller; the deliverable names it instead of hiding it. */
 57	  undefinedAspects: z.array(z.enum(["thesis", "meeting_type", "format", "audience", "depth"])).default([]),
 58	  confirmedPlanId: z.string().nullable().default(null),
 59	}).strict();
 60	
 61	export const candidateQuestionSchema = z.object({
 62	  id: identifier,
 63	  text: nonEmpty,
 64	  /** Why the answer changes the material; a question without a real reason is not asked. */
 65	  changesTheWork: nonEmpty,
 66	  /** The declared search of the base: which documents were checked and what was found; a question without a search is not asked, and a found answer refuses it. */
 67	  coverage: z.object({searched: z.array(nonEmpty).min(1), answeredBy: anchorSchema.nullable(), answer: nonEmpty.nullable()}).strict().nullable().default(null),
 68	  /** How much the answer changes the material, from the coverage map: lower asks first. */
 69	  priority: z.number().int().nonnegative(),
 70	}).strict();
 71	
 72	export const previousVersionSchema = z.object({
 73	  outputFingerprint: sha256,
 74	  blocks: z.array(z.object({id: identifier, state: z.enum(["filled", "gap"]), objectIds: z.array(identifier)}).strict()),
 75	  objectFingerprints: z.record(identifier, sha256),
 76	}).strict();
 77	
 78	export const briefInputSchema = z.object({
 79	  caseId: nonEmpty,
 80	  request: briefRequestSchema,
 81	  objects: z.array(approvedObjectSchema),
 82	  candidateQuestions: z.array(candidateQuestionSchema).default([]),
 83	  previousVersion: previousVersionSchema.nullable().default(null),
 84	}).strict().superRefine((input, context) => {
 85	  const objectIds = new Set<string>();
 86	  input.objects.forEach((object, index) => {
 87	    if (objectIds.has(object.id)) context.addIssue({code: "custom", path: ["objects", index], message: `duplicate object ${object.id}`});
 88	    objectIds.add(object.id);
 89	    object.headlines.forEach((headline, position) => {
 90	      if (headline.objectFingerprint !== object.fingerprint) context.addIssue({code: "custom", path: ["objects", index, "headlines", position], message: `${object.id}: the headline is bound to another fingerprint than the object's`});
 91	      if (headline.unit === null && /\d{1,3}(\.\d{3})+/.test(headline.text)) context.addIssue({code: "custom", path: ["objects", index, "headlines", position], message: `${object.id}: a fact with a figure needs its unit`});
 92	      if (/rompid|rompiment|breach|descumpr|inadimpl|default declar/i.test(headline.text)) context.addIssue({code: "custom", path: ["objects", index, "headlines", position], message: `${object.id}: a fact asserts a breach or a default; no object asserts a legal event, only an interim reading against a limit`});
 93	      if (headline.unit !== null && object.unit !== null && /\d{1,3}(\.\d{3})+/.test(headline.text) && headline.unit.toLowerCase() !== object.unit.toLowerCase()) context.addIssue({code: "custom", path: ["objects", index, "headlines", position], message: `${object.id}: the fact quotes a figure in ${headline.unit} and the object states its figures in ${object.unit}`});
 94	      if (headline.unit !== null) {
 95	        const words = headline.text.toLowerCase();
 96	        const unit = headline.unit.toLowerCase();
 97	        const saysThousand = /\bmil\b|thousand/.test(words) && !/milh/.test(words);
 98	        const saysMillion = /milh[õo]es|million/.test(words);
 99	        if (saysThousand && /milh|million/.test(unit)) context.addIssue({code: "custom", path: ["objects", index, "headlines", position], message: `${object.id}: the fact says thousands and its unit says millions`});
100	        if (saysMillion && /\bmil\b|thousand/.test(unit) && !/milh/.test(unit)) context.addIssue({code: "custom", path: ["objects", index, "headlines", position], message: `${object.id}: the fact says millions and its unit says thousands`});
101	      }
102	    });
103	  });
104	  const questionIds = new Set<string>();
105	  input.candidateQuestions.forEach((question, index) => {
106	    if (questionIds.has(question.id)) context.addIssue({code: "custom", path: ["candidateQuestions", index], message: `duplicate question ${question.id}`});
107	    questionIds.add(question.id);
108	    if (question.coverage && (question.coverage.answeredBy === null) !== (question.coverage.answer === null)) context.addIssue({code: "custom", path: ["candidateQuestions", index, "coverage"], message: `${question.id}: an answer and its anchor come together`});
109	  });
110	  const blockIds = new Set<string>();
111	  input.previousVersion?.blocks.forEach((block, index) => {
112	    if (blockIds.has(block.id)) context.addIssue({code: "custom", path: ["previousVersion", "blocks", index], message: `duplicate block ${block.id} in the previous version`});
113	    blockIds.add(block.id);
114	  });
115	  if (input.request.pages !== null && (input.request.form === "first_deliverable" || input.request.form === null)) context.addIssue({code: "custom", path: ["request", "pages"], message: "the first deliverable has no page plan; pages belong to a material form"});
116	});
117	export type BriefInput = z.input<typeof briefInputSchema>;
118	
119	type Kind = (typeof objectKinds)[number];
120	type Stance = "for" | "against" | "neutral";
121	const BLOCKS: Array<{id: string; label: string; needs: Kind[]; stance: Stance | null}> = [
122	  {id: "company_view", label: "Visão da companhia", needs: ["company_view"], stance: null},
123	  {id: "performance_outlook", label: "Desempenho histórico e outlook", needs: ["performance"], stance: null},
124	  {id: "debt_by_instrument", label: "Dívida por instrumento", needs: ["debt_ledger"], stance: null},
125	  {id: "maturity_schedule", label: "Cronograma de vencimentos", needs: ["maturity_wall"], stance: null},
126	  {id: "liquidity_coverage", label: "Liquidez e cobertura", needs: ["maturity_wall", "interest_schedule"], stance: null},
127	  {id: "assumptions", label: "Premissas preliminares", needs: ["scenarios"], stance: null},
128	  {id: "points_for_thesis", label: "Pontos que sustentam a tese", needs: [], stance: "for"},
129	  {id: "points_against_thesis", label: "Pontos contra a tese", needs: [], stance: "against"},
130	  {id: "initial_alternatives", label: "Alternativas iniciais", needs: ["before_after"], stance: null},
131	  {id: "open_questions", label: "Perguntas pendentes", needs: [], stance: null},
132	  {id: "exhibits", label: "Exhibits preliminares", needs: ["debt_ledger", "maturity_wall"], stance: null},
133	];
134	
135	const PAGE_PLANS: Record<"pitch_pages" | "internal_briefing" | "analysis_with_scenarios" | "board_deck", Array<{title: string; blocks: string[]}>> = {
136	  pitch_pages: [
137	    {title: "Situação atual", blocks: ["debt_by_instrument", "maturity_schedule", "liquidity_coverage", "points_against_thesis"]},
138	    {title: "Alternativas", blocks: ["initial_alternatives", "points_for_thesis"]},
