170	/** Fits the base layout to the pages asked: merges the tail when fewer, splits the fullest page when more. */
171	function fitPages(base: Array<{title: string; blocks: string[]}>, pages: number | null): Array<{title: string; blocks: string[]}> | null {
172	  const layout = base.map((page) => ({title: page.title, blocks: [...page.blocks]}));
173	  if (pages === null || pages === layout.length) return layout;
174	  if (pages < layout.length) {
175	    while (layout.length > pages) {
176	      const last = layout.pop()!;
177	      const previous = layout[layout.length - 1]!;
178	      previous.title = `${previous.title} e ${last.title.toLowerCase()}`;
179	      previous.blocks.push(...last.blocks);
180	    }
181	    return layout;
182	  }
183	  const totalBlocks = layout.reduce((sum, page) => sum + page.blocks.length, 0);
184	  if (pages > totalBlocks) return null;
185	  while (layout.length < pages) {
186	    const index = layout.reduce((best, page, position) => (page.blocks.length > layout[best]!.blocks.length ? position : best), 0);
187	    const page = layout[index]!;
188	    const half = Math.ceil(page.blocks.length / 2);
189	    layout.splice(index + 1, 0, {title: `${page.title} (continuação)`, blocks: page.blocks.slice(half)});
190	    page.blocks = page.blocks.slice(0, half);
191	  }
192	  return layout;
193	}
