179	    const permute = <T>(items: readonly T[], seed: number): T[] => { const copy = [...items]; let state = seed; for (let index = copy.length - 1; index > 0; index -= 1) { state = (state * 1103515245 + 12345) % 2147483648; const swap = state % (index + 1); [copy[index], copy[swap]] = [copy[swap]!, copy[index]!]; } return copy; };
180	    const reversedKeys = <T,>(value: T): T => (Array.isArray(value) ? value.map(reversedKeys) as T : value && typeof value === "object" ? Object.fromEntries(Object.entries(value as Record<string, unknown>).reverse().map(([key, inner]) => [key, reversedKeys(inner)])) as T : value);
181	    for (let seed = 1; seed <= 20; seed += 1) {
182	      const shuffled = base();
183	      shuffled.objects = permute(shuffled.objects, seed).map((object) => ({...object, headlines: permute(object.headlines ?? [], seed + 1)}));
184	      shuffled.candidateQuestions = permute(shuffled.candidateQuestions!, seed + 2).map((question) => (question.coverage ? {...question, coverage: {...question.coverage, searched: permute(question.coverage.searched, seed + 6)}} : question));
185	      shuffled.request = {...shuffled.request, audience: {primary: "vp", others: permute(["companhia", "md", "associado"], seed + 3)}, undefinedAspects: permute(["format", "thesis"], seed + 4)};
186	      shuffled.previousVersion = {...shuffled.previousVersion!, blocks: permute(shuffled.previousVersion!.blocks, seed + 5)};
187	      const again = planMeetingBrief(seed % 2 ? reversedKeys(shuffled) : shuffled);
188	      expect(again.trace.inputFingerprint).toBe(first.trace.inputFingerprint);
189	      expect(again.trace.outputFingerprint).toBe(first.trace.outputFingerprint);
